static void blacklist_del_num_to_flash(lv_obj_t * ui_Screen)
{
    blacklist_data_t * p_blacklist_data;
    ui_screen_blacklist_del_num_obj_t * p_screen_param;
    uint32_t        copy_size,write_size;

    p_screen_param      = (ui_screen_blacklist_del_num_obj_t *) lv_obj_get_user_data(ui_Screen);
    p_blacklist_data    = p_screen_param->enter_param.p_blacklist_data;

    if (p_blacklist_data->head.count - 1 > p_screen_param->enter_param.focus_index)
        copy_size =
             (p_blacklist_data->head.count - 1 - p_screen_param->enter_param.focus_index) *sizeof(blacklist_param_t);
    else 
        copy_size = 0;

    if (copy_size)
        memcpy(&p_blacklist_data->num_array[p_screen_param->enter_param.focus_index],
            &p_blacklist_data->num_array[p_screen_param->enter_param.focus_index + 1],copy_size);

    if (p_blacklist_data->head.count > 0)
        p_blacklist_data->head.count--;

    write_size          = sizeof(blacklist_head_t) +p_blacklist_data->head.count * sizeof(blacklist_param_t);

    blacklist_wirte_flash_data(p_blacklist_data,write_size);
}


